#include <set>
#include <iostream>

int main() {
    std::set<int> s = {1, 2, 3};

    // Successful insertion
    auto res1 = s.insert(4);
    std::cout << "Inserted 4: " << res1.second << "\n";

    // Failed insertion (duplicate)
    auto res2 = s.insert(2);
    std::cout << "Inserted 2: " << res2.second << "\n";

    // Iterator points to the existing element 2
    if (!res2.second) {
        std::cout << "Existing element found: " << *res2.first << "\n";
    }
}
